create table public.ltspn_ballots (
 week_id uuid not null references public.weeks(id),
 user_id uuid not null references public.profiles(id),
 teams text[] not null,
 primary key(week_id,user_id),
 check(cardinality(teams)=25)
);
alter table public.ltspn_ballots enable row level security;
grant select,insert,update on public.ltspn_ballots to authenticated;
create policy members_read_ballots on public.ltspn_ballots for select to authenticated using (exists(select 1 from public.profiles where id=auth.uid()));
create policy own_active_ballot_insert on public.ltspn_ballots for insert to authenticated with check (
 user_id=auth.uid() and exists(select 1 from public.weeks where id=week_id and is_active and questions_released_at is not null)
);
create policy own_active_ballot_update on public.ltspn_ballots for update to authenticated using (
 user_id=auth.uid() and exists(select 1 from public.weeks where id=week_id and is_active and questions_released_at is not null)
) with check (
 user_id=auth.uid() and exists(select 1 from public.weeks where id=week_id and is_active and questions_released_at is not null)
);
create function private.validate_ltspn_ballot() returns trigger language plpgsql security invoker set search_path='' as $$
begin
 if (select count(distinct t.id) from unnest(new.teams) v(id) join public.ltspn_poll_teams t on t.id=v.id)<>25 then
 raise exception 'Choose 25 different college teams.';
 end if;
 if TG_OP='UPDATE' and (new.week_id<>old.week_id or new.user_id<>old.user_id) then
 raise exception 'Ballot ownership and week cannot change.';
 end if;
 return new;
end $$;
create trigger validate_ltspn_ballot before insert or update on public.ltspn_ballots for each row execute function private.validate_ltspn_ballot();
